    __shared__ float tile_A[TILE_DIM][TILE_DIM];
    __shared__ float tile_B[TILE_DIM][TILE_DIM];

    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // Each thread computes a 4x4 sub-tile of C
    float C_sub_tile[VEC_SIZE][VEC_SIZE] = {0.0f};

    int row = block_row * TILE_DIM + thread_row;
    int col = block_col * TILE_DIM + thread_col;

    for (int t = 0; t < N / TILE_DIM; ++t) {
